// 作用：只整理上传文件，不操作文件系统。
// Code 节点不使用 fs、不创建目录、不读写本地文件。
const item = $input.first();
const binary = item.binary || {};
const firstBinaryKey = Object.keys(binary)[0];

if (!firstBinaryKey) {
  throw new Error('没有收到 CSV 文件。请在表单的 health_topics_csv 字段上传 .csv 文件。');
}

const limitFromForm = Number(item.json.today_limit || 5);
const safeLimit = Number.isFinite(limitFromForm) && limitFromForm > 0 ? Math.floor(limitFromForm) : 5;

return [{
  json: {
    today_limit: safeLimit,
    today_focus: item.json.today_focus || '',
    input_file_name: '/files/health_topics.csv',
    json_output_file_name: '/files/agent1_ranked_health_topics.json',
    markdown_report_file_name: '/files/agent1_decision_report.md'
  },
  binary: {
    data: binary[firstBinaryKey]
  }
}];

// 作用：只做数据处理：解析 CSV、评分、生成 JSON 文本和 Markdown 文本。
// 严格不使用 fs、node:fs，也不创建目录、不读写本地文件。
function getCsvText(item) {
  if (typeof item.json.data === 'string') return item.json.data;
  if (typeof item.json.text === 'string') return item.json.text;
  if (typeof item.json.fileContent === 'string') return item.json.fileContent;
  for (const value of Object.values(item.json)) {
    if (typeof value === 'string' && value.includes('title') && value.includes('ingredient')) {
      return value;
    }
  }
  throw new Error('无法从 Extract From File 节点读取 CSV 文本。请确认上传的是 UTF-8 CSV 文件。');
}

function parseCsv(text) {
  const rows = [];
  let current = '';
  let row = [];
  let inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    const next = text[i + 1];

    if (char === '"' && inQuotes && next === '"') {
      current += '"';
      i++;
    } else if (char === '"') {
      inQuotes = !inQuotes;
    } else if (char === ',' && !inQuotes) {
      row.push(current);
      current = '';
    } else if ((char === '\n' || char === '\r') && !inQuotes) {
      if (char === '\r' && next === '\n') i++;
      row.push(current);
      if (row.some((value) => value.trim() !== '')) rows.push(row);
      row = [];
      current = '';
    } else {
      current += char;
    }
  }

  row.push(current);
  if (row.some((value) => value.trim() !== '')) rows.push(row);
  return rows;
}

function clampScore(value) {
  const number = Number(value);
  if (!Number.isFinite(number)) return 1;
  return Math.max(1, Math.min(5, Math.round(number)));
}

function escapeRegex(word) {
  return word.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function containsWord(text, word) {
  return new RegExp('(^|[^a-zA-Z])' + escapeRegex(word) + '($|[^a-zA-Z])', 'i').test(text);
}

function riskInfo(topic) {
  const combined = [topic.title, topic.ingredient, topic.angle, topic.target_audience, topic.suggested_hook].join(' ');
  const highRiskWords = ['cure', 'cures', 'treat', 'treats', 'treatment', 'prevent', 'prevents', 'reverse', 'reverses', 'diabetes', 'cancer', 'hypertension'];
  const lowRiskWords = ['tea', 'caffeine', 'routine', 'evening routine', 'screen fatigue'];
  const highHits = highRiskWords.filter((word) => containsWord(combined, word));
  const lowHits = lowRiskWords.filter((word) => combined.toLowerCase().includes(word.toLowerCase()));

  if (highHits.length > 0) {
    return { score: 5, alerts: ['包含高风险健康词：' + highHits.join(', ') + '。发布前必须人工改写。'], status: 'needs_compliance_rewrite' };
  }
  if (lowHits.length > 0) {
    return { score: 2, alerts: ['偏日常健康习惯，命中低风险方向：' + lowHits.join(', ') + '。'], status: 'approved_for_script' };
  }
  return { score: 1, alerts: ['未发现明显高风险词，但仍需人工确认。'], status: 'approved_for_script' };
}

function grade(score) {
  if (score >= 25) return 'A';
  if (score >= 20) return 'B';
  return 'C';
}

function priority(item) {
  if (item.recommendation_grade === 'A' && item.is_recommended_for_production === 'Yes') return '立即制作';
  if (item.recommendation_grade === 'B' && item.is_recommended_for_production === 'Yes') return '观察';
  return '暂缓';
}

const sourceItem = $input.first();
const setup = $('2. 标准化上传文件').item.json;
const limit = Number(setup.today_limit || 5);
const csvText = getCsvText(sourceItem).replace(/^\uFEFF/, '');
const rows = parseCsv(csvText);

if (rows.length < 2) {
  throw new Error('CSV 至少需要 1 行表头和 1 行选题数据。');
}

const headers = rows[0].map((header) => header.trim());
const required = ['title', 'ingredient', 'angle', 'target_audience', 'curiosity', 'pain', 'product_fit', 'visual_potential', 'repeatability', 'suggested_hook'];
const missing = required.filter((field) => !headers.includes(field));
if (missing.length > 0) {
  throw new Error('CSV 缺少必填字段：' + missing.join(', '));
}

const topics = rows.slice(1).map((values, index) => {
  const topic = {};
  headers.forEach((header, i) => { topic[header] = values[i] || ''; });
  const scores = {
    curiosity: clampScore(topic.curiosity),
    pain: clampScore(topic.pain),
    product_fit: clampScore(topic.product_fit),
    visual_potential: clampScore(topic.visual_potential),
    repeatability: clampScore(topic.repeatability)
  };
  const risk = riskInfo(topic);
  const total = scores.curiosity * 2 + scores.pain * 2 + scores.product_fit + scores.visual_potential + scores.repeatability - risk.score * 2;
  const recommendationGrade = grade(total);
  const recommended = risk.score >= 5 ? 'No' : 'Yes';
  const reason = recommended === 'No'
    ? '暂不推荐直接制作《' + topic.title + '》，因为存在明显健康合规风险，应先人工改写。'
    : recommendationGrade === 'A'
      ? '推荐优先制作《' + topic.title + '》，因为它在好奇心、痛点强度、产品匹配度、画面表现力、系列化潜力上表现强，且风险可控。'
      : '可以作为备选制作《' + topic.title + '》，它有一定潜力，但需要进一步优化钩子或商业角度。';

  return {
    row_number: index + 2,
    title: topic.title,
    ingredient: topic.ingredient,
    angle: topic.angle,
    target_audience: topic.target_audience,
    total_score: total,
    recommendation_grade: recommendationGrade,
    is_recommended_for_production: recommended,
    recommendation_reason: reason,
    risk_score: risk.score,
    risk_alerts: risk.alerts,
    status: risk.status,
    score_details: scores,
    suggested_hook: topic.suggested_hook
  };
});

const ranked = topics.sort((a, b) => b.total_score - a.total_score).slice(0, limit);
const jsonText = JSON.stringify(ranked, null, 2);

const lines = [];
lines.push('# Agent 1 V1.1 Decision Report：今日健康选题决策报告');
lines.push('');
lines.push('## 使用说明');
lines.push('');
lines.push('这份报告只用于决定今天优先制作哪些健康短视频选题。');
lines.push('当前报告由 n8n 官方节点工作流生成；Code 节点只做数据处理，不操作文件系统，不开发 Agent 2。');
lines.push('');
lines.push('## 今日推荐 Top ' + ranked.length + ' 选题');
lines.push('');
lines.push('| 排名 | 选题 | 综合评分 | 推荐等级 | 推荐制作 | 建议优先级 |');
lines.push('| --- | --- | ---: | --- | --- | --- |');
ranked.forEach((item, index) => {
  lines.push('| ' + (index + 1) + ' | ' + item.title + ' | ' + item.total_score + ' | ' + item.recommendation_grade + ' | ' + item.is_recommended_for_production + ' | ' + priority(item) + ' |');
});
lines.push('');
lines.push('## 单条选题决策详情');
ranked.forEach((item, index) => {
  lines.push('');
  lines.push('### ' + (index + 1) + '. ' + item.title);
  lines.push('');
  lines.push('- 综合评分：' + item.total_score);
  lines.push('- 推荐等级：' + item.recommendation_grade);
  lines.push('- 推荐制作：' + item.is_recommended_for_production);
  lines.push('- 建议优先级：' + priority(item));
  lines.push('- 推荐原因：' + item.recommendation_reason);
  lines.push('- 风险提醒：' + item.risk_alerts.join('；'));
});
lines.push('');
lines.push('## 下一步');
lines.push('');
lines.push('请先人工确认这份报告。确认前不要开发 Agent 2。');
const markdownText = lines.join('\n');

return [{
  json: {
    ranked_health_topics: ranked,
    decision_report_markdown: markdownText,
    json_output_file_name: setup.json_output_file_name,
    markdown_report_file_name: setup.markdown_report_file_name
  },
  binary: {
    json_file: {
      data: Buffer.from(jsonText, 'utf8').toString('base64'),
      mimeType: 'application/json',
      fileName: setup.json_output_file_name
    },
    markdown_file: {
      data: Buffer.from(markdownText, 'utf8').toString('base64'),
      mimeType: 'text/markdown',
      fileName: setup.markdown_report_file_name
    }
  }
}];
